import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context'
import { PRODUCTS_ACTION } from '../actions'

export const useProductsContext = () => {
  const [{ addProductData, productDetailData, productPlansData, updateProductPlansData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const addProductRequest = (payload = {}) => {
    callApi(PRODUCTS_ACTION.addProduct({ body: payload }))
  }

  const getProductDetail = (payload = {}) => {
    callApi(PRODUCTS_ACTION.getProductDetail({ query: payload }))
  }

  const getProductPlans = (payload = {}) => {
    callApi(PRODUCTS_ACTION.getProductPlans({ query: payload }))
  }

  const updateProductPlansRequest = (payload = {}) => {
    callApi(PRODUCTS_ACTION.updateProductPlans({ body: payload }))
  }

  const updateProductInfoRequest = (payload = {}) => {
    callApi(PRODUCTS_ACTION.updateProductInfo({ body: payload }))
  }

  return {
    addProductRequest,
    addProductData,
    getProductDetail,
    productDetailData,
    getProductPlans,
    productPlansData,
    updateProductPlansRequest,
    updateProductPlansData,
    updateProductInfoRequest
  }
}

export const useDefaultBenefitGroups = () => {
  const [{ defaultBenefitGroupsData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const defaultBenefitGroupsRequest = (payload = {}) => {
    callApi(PRODUCTS_ACTION.getExistingBenefitGroup({ query: payload }))
  }
  return { defaultBenefitGroupsData, defaultBenefitGroupsRequest }
}

export const useCompanyDetails = () => {
  const [{ companyDetailData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const companyDetailRequest = (payload = {}) => {
    callApi(PRODUCTS_ACTION.getCompanyDetails({ query: payload }))
  }
  return { companyDetailData, companyDetailRequest }
}
