import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, Icon, Modal } from 'antd'
import { useCallback, useEffect } from 'react'
import { downloadDataFromUrl } from '../../../../../helpers/utility'
import { useExportExcel, useResetState } from '../../state/hooks'

const ExportExcel = ({ url, queryParams, disabled, buttonContent, buttonType, buttonSize }) => {
  const { exportExcelRequest, exportExcelData } = useExportExcel()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const [{ EXPORT_EXCEL_ERROR, exportExcelStatus }] = useErrorContextValue()
  const [{ EXPORT_EXCEL_LOADER }] = useLoaderContextValue()
  const handleExportExcel = useCallback(() => {
    exportExcelRequest({ url, ...queryParams })
  }, [exportExcelRequest, url, queryParams])

  useEffect(() => {
    if (exportExcelStatus === 'success' && exportExcelData && exportExcelData.url) {
      downloadDataFromUrl(exportExcelData.url)
    }
  }, [exportExcelData, exportExcelStatus])

  useEffect(() => {
    return () => {
      resetState(['exportExcelData'])
      resetError(['exportExcelStatus', 'EXPORT_EXCEL_ERROR'])
    }
  }, [resetError, resetState])

  useEffect(() => {
    if (EXPORT_EXCEL_ERROR) {
      Modal.error({ title: exportExcelStatus })
    }
  }, [EXPORT_EXCEL_ERROR, exportExcelStatus])

  return (
    <Button
      type={buttonType || 'primary'}
      onClick={handleExportExcel}
      disabled={disabled}
      size={buttonSize}
      loading={!!EXPORT_EXCEL_LOADER}
    >
      {
        buttonContent ||
          <>Export Excel <Icon type='file-excel' /></>
      }
    </Button>
  )
}
export default ExportExcel
