const tsiPattern = /^-1$|^\d+(\.\d+)*$|^\d+(\.\d+)*\/tahun$|^\d+(\.\d+)*\/hari$/
const yearlyLimitPattern = /^\d+(\.\d+)*$/
const tsiFormatError = 'Invalid format. Allowed formats are -1, 5.000.500, 5.000.5000/hari, 5.000.500/tahun'
const yearlyLimitError = 'Invalid format. Allowed format is 5.000.500'

export function tsiValidator (form, benefitGroupName, rowData, planIndex, benefitGroupSlug) {
  if (benefitGroupSlug === 'asuransi-jiwa') {
    let asuransiJiwaRules = [
      {
        max: 25,
        message: 'TSI cannot be more than 25 characters'
      }
    ]
    if (rowData.benefit === 'Yearly Limit') {
      asuransiJiwaRules.push({
        pattern: yearlyLimitPattern,
        message: yearlyLimitError
      })
      asuransiJiwaRules.push({
        required: true,
        message: 'Yearly Limit is required.'
      })
      asuransiJiwaRules.push({
        validator: (_, value) => {
          if (!value) {
            return Promise.resolve()
          }
          value = String(value).split('/')[0]
          value = value.replace(/\./g, '')
          const valueAsNumber = Number(value)
          if (valueAsNumber > 0) {
            if (value.length > 9) {
              return Promise.reject(new Error('Yearly limit should not have more than 9 digits'))
            }
            return Promise.resolve()
          } else {
            return Promise.reject(new Error('Yearly Limit should be greater than 0'))
          }
        }
      })
      asuransiJiwaRules = asuransiJiwaRules.slice(1)
    } else {
      asuransiJiwaRules.push(
        {
          validator: (_, value) => {
            let yearlyLimit = form.getFieldValue(`${benefitGroupName}.${planIndex}.Yearly Limit`)
            yearlyLimit = String(yearlyLimit).replace(/\./g, '')
            yearlyLimit = Number(yearlyLimit)
            const originalValue = value
            if (!value) {
              return Promise.resolve()
            }
            value = String(value).split('/')[0]
            value = value.replace(/\./g, '')
            const valueAsNumber = Number(value)
            if (String(originalValue).split('/').length > 2 || isNaN(valueAsNumber)) {
              return Promise.resolve()
            }
            if (String(originalValue).split('/').length === 2 && !['tahun', 'hari'].includes(String(originalValue).split('/')[1])) {
              return Promise.reject(new Error(`Wrong TSI period - ${String(originalValue).split('/')[1]}`))
            }
            if (valueAsNumber === -1) {
              return Promise.resolve()
            }
            if (valueAsNumber > 0) {
              if (value.length > 9) {
                return Promise.reject(new Error('TSI should not have more than 9 digits'))
              }
              if (yearlyLimit && valueAsNumber > yearlyLimit) {
                return Promise.reject(new Error('TSI should not be greater than yearly limit'))
              }
              return Promise.resolve()
            } else {
              return Promise.reject(new Error('TSI should be greater than 0 or -1'))
            }
          }
        }
      )
    }
    return asuransiJiwaRules
  }
  return [
    {
      required: form.getFieldValue(`${benefitGroupName}.0.limit_type`) === 'inner' || rowData.benefit === 'Yearly Limit',
      message: 'This field is required.'
    },
    {
      pattern: rowData.benefit === 'Yearly Limit' ? yearlyLimitPattern : tsiPattern,
      message: rowData.benefit === 'Yearly Limit' ? yearlyLimitError : tsiFormatError
    },
    {
      validator: (_, value) => {
        let yearlyLimit = form.getFieldValue(`${benefitGroupName}.${planIndex}.Yearly Limit`)
        yearlyLimit = String(yearlyLimit).replace(/\./g, '')
        yearlyLimit = Number(yearlyLimit)
        if (!value) {
          return Promise.resolve()
        }
        value = String(value).split('/')[0]
        value = value.replace(/\./g, '')
        const valueAsNumber = Number(value)
        if (rowData.benefit === 'Yearly Limit') {
          if (valueAsNumber > 0) {
            if (value.length > 9) {
              return Promise.reject(new Error('Yearly limit should not have more than 9 digits'))
            }
            return Promise.resolve()
          } else {
            return Promise.reject(new Error('Yearly Limit should be greater than 0'))
          }
        } else {
          if (valueAsNumber === -1) {
            return Promise.resolve()
          }
          if (valueAsNumber > 0) {
            if (value.length > 9) {
              return Promise.reject(new Error('TSI should not have more than 9 digits'))
            }
            if (yearlyLimit && valueAsNumber > yearlyLimit) {
              return Promise.reject(new Error('TSI should not be greater than yearly limit'))
            }
            return Promise.resolve()
          } else {
            return Promise.reject(new Error('TSI should be greater than 0 or -1'))
          }
        }
      }
    }
  ]
}
