import { PRODUCTS_ACTION } from './actions'

const reducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case PRODUCTS_ACTION.ADD_PRODUCT:
    case PRODUCTS_ACTION.PRODUCT_DETAIL:
    case PRODUCTS_ACTION.PRODUCT_PLANS:
    case PRODUCTS_ACTION.UPDATE_PRODUCT_PLANS:
    case PRODUCTS_ACTION.UPDATE_PRODUCT_INFO:
    case PRODUCTS_ACTION.DEFAULT_BENEFIT_GROUPS:
    case PRODUCTS_ACTION.COMPANY_DETAIL:
      return { ...state, ...payload }
    default:
      return state
  }
}

export default reducer
