import ebUrls from '../../../../../request/urls/employeeBenefit'

export const PRODUCTS_ACTION = {
  ADD_PRODUCT_REQUEST: 'ADD_PRODUCT_REQUEST',
  ADD_PRODUCT: 'ADD_PRODUCT',
  PRODUCT_DETAIL_REQUEST: 'PRODUCT_DETAIL_REQUEST',
  PRODUCT_DETAIL: 'PRODUCT_DETAIL',
  PRODUCT_PLANS_REQUEST: 'PRODUCT_PLANS_REQUEST',
  PRODUCT_PLANS: 'PRODUCT_PLANS',
  UPDATE_PRODUCT_PLANS_REQUEST: 'UPDATE_PRODUCT_PLANS_REQUEST',
  UPDATE_PRODUCT_PLANS: 'UPDATE_PRODUCT_PLANS',
  UPDATE_PRODUCT_INFO_REQUEST: 'UPDATE_PRODUCT_INFO_REQUEST',
  UPDATE_PRODUCT_INFO: 'UPDATE_PRODUCT_INFO',
  DEFAULT_BENEFIT_GROUPS_REQUEST: 'DEFAULT_BENEFIT_GROUPS_REQUEST',
  DEFAULT_BENEFIT_GROUPS: 'DEFAULT_BENEFIT_GROUPS',
  COMPANY_DETAIL_REQUEST: 'COMPANY_DETAIL_REQUEST',
  COMPANY_DETAIL: 'COMPANY_DETAIL',
  updateProductInfo: payload => ({
    type: PRODUCTS_ACTION.UPDATE_PRODUCT_INFO_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateProductInfo
    }
  }),
  updateProductPlans: payload => ({
    type: PRODUCTS_ACTION.UPDATE_PRODUCT_PLANS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateProductBenefits
    }
  }),

  getProductPlans: payload => ({
    type: PRODUCTS_ACTION.PRODUCT_PLANS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getProductPlans
    }
  }),

  getProductDetail: payload => ({
    type: PRODUCTS_ACTION.PRODUCT_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getProductDetails
    }
  }),
  addProduct: payload => ({
    type: PRODUCTS_ACTION.ADD_PRODUCT_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addProduct
    }
  }),
  getExistingBenefitGroup: payload => ({
    type: PRODUCTS_ACTION.DEFAULT_BENEFIT_GROUPS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.existingBenefitGroups
    }
  }),
  getCompanyDetails: (payload) => ({
    type: PRODUCTS_ACTION.COMPANY_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.companyDetails
    }
  })
}
